const bat='<svg viewBox="0 0 100 60" aria-hidden="true"><path class="bat-wing-left" d="M50 35 30 8 5 2 12 23 1 35Q17 23 22 44Q36 31 43 50Z" fill="currentColor"/><path class="bat-wing-right" d="M50 35 70 8 95 2 88 23 99 35Q83 23 78 44Q64 31 57 50Z" fill="currentColor"/><path d="m43 27 2-16 5 8 5-8 2 16q8 19-7 28-15-9-7-28" fill="currentColor"/></svg>';
const dragon='<svg viewBox="0 0 340 190" aria-hidden="true"><g class="dragon-wings" fill="currentColor"><path d="M150 96Q92 26 32 4L50 54 4 34 40 84 12 104Q60 80 84 116L112 90 148 126Z"/><path d="M148 94Q186 20 250 6L230 48 280 26 250 74 288 78Q232 94 224 120L186 100Z"/></g><path d="M120 96q28-40 70-30 24 6 30 26 10-14 26-12l-8 14 16 4-18 8q2 26-22 34-26 8-46-6l-18 22-6-26q-26 4-38-10-8-8 6-24Z" fill="currentColor"/><circle cx="196" cy="84" r="3.4" fill="#ff9c2a"/><path d="M214 88q22 6 34 2l-6 12-12 4-14-8Z" fill="#ffb950"/><path class="dragon-breath" d="M246 90q34-10 54 6-26 4-38 16-8-12-16-22Z" fill="#ffa63a"/></svg>';
const demon='<svg viewBox="0 0 100 160" aria-hidden="true"><path d="M32 26 26 2 42 18ZM68 26 74 2 58 18Z" fill="currentColor"/><path d="M50 14c17 0 27 12 27 27 0 12-6 20-6 26l8 34-10 4-4 38H35l-4-38-10-4 8-34c0-6-6-14-6-26 0-15 10-27 27-27Z" fill="currentColor"/><g class="demon-arm"><path d="M24 68 6 92l6 8 20-18ZM76 68 94 92l-6 8-20-18Z" fill="currentColor"/></g><circle class="demon-eye" cx="41" cy="40" r="3.6"/><circle class="demon-eye" cx="59" cy="40" r="3.6"/><path d="M40 56q10 8 20 0" stroke="currentColor" stroke-width="3" fill="none"/></svg>';

